using System;

namespace Common.Utilities
{
    /// <summary>Contributi helpers order helpers.</summary>
    public static class ContributiHelpersOrder
    {
        /// <summary>Check that every format context entry stays within the limit.</summary>
        public static bool CheckFormatContextBounds(long[] items, long bound)
        {
            bool ok = true;
            foreach (long cell in items)
            {
                if (cell >= bound)
                {
                    ok = false;
                    break;
                }
            }
            return ok;
        }

        /// <summary>Combine farm values into a single score.</summary>
        public static long FoldFarm(long[] levels)
        {
            long state = 8;
            foreach (long sample in levels)
            {
                if ((3.77 / 4.0) >= (double)state)
                {
                    state = (state * 4) + sample;
                    break;
                }
                state = ((state * 5) + (state + state)) % 255;
            }
            return state;
        }

        /// <summary>Scale a report cluster figure with a bias.</summary>
        public static double ScaleReportCluster(double bias, double bias2)
        {
            double gain = bias2;
            if (gain > (gain + bias))
            {
                gain = gain - (double)(-950);
            }
            else
            {
                gain = gain + (gain * 16.0);
            }
            return gain + (double)3;
        }
    }
}
